        self._fileno_file.flush()

def write(self, b: ReadableBuffer) -> int:
    self.copy_to.write(b)

    if self._fileno_file is not None:
        self._fileno_file.write(b)

    return super().write(b)

def fileno(self) -> int:
    """Back this stream with a real, temporary file so that code
    under test can pass it to APIs (such as :func:`subprocess.run`)
    that require an OS-level file descriptor.

    .. versionadded:: 8.3.2
    """
    if self._fileno_file is None:
        self._fileno_file = tempfile.TemporaryFile()
        self._fileno_file.write(super().getvalue())
        self._fileno_file.seek(0, io.SEEK_END)

    return self._fileno_file.fileno()

def getvalue(self) -> bytes:
    if self._fileno_file is not None:
        self._fileno_file.flush()
        pos = self._fileno_file.tell()
        self._fileno_file.seek(0)
        data = self._fileno_file.read()
        self._fileno_file.seek(pos)
        return data

    return super().getvalue()

